   */
  def put_concrete_inputs(batch_signal : EIT_Acquisition_Supervisor.BatchSignal.Type): Unit = {
    put_batch_signal(batch_signal)
  }


  /** helper function to check BatchAssessment_acquisition_process_batch_assessment's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param batch_facts method that will be called with the value of the outgoing data
   *        port 'batch_facts'.
   */
  def check_concrete_output(batch_facts: EIT_Acquisition_Supervisor.BatchFacts.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val batch_factsValue: EIT_Acquisition_Supervisor.BatchFacts.Type = get_batch_facts().get
    if(!batch_facts(batch_factsValue)) {
      testFailures = testFailures :+ st"'batch_facts' did not match expected: value of the outgoing data port is ${batch_factsValue}"
