  // getter for out DataPort
  def get_batch_facts(): Option[EIT_Acquisition_Supervisor.BatchFacts.Type] = {
    val value: Option[EIT_Acquisition_Supervisor.BatchFacts.Type] = get_batch_facts_payload() match {
      case Some(EIT_Acquisition_Supervisor.BatchFacts_Payload(v)) => Some(v)
